{
  "id": "rw-compound-comp",
  "family": "lending",
  "split": "realworld",
  "issue_report": "After the Comptroller upgrade of Compound Proposal 62 (`CompRewards.upgrade`), accounts that held a position before the upgrade in a market that never had COMP rewards are credited COMP that was never emitted. Example, from mainnet: in cSUSHI both reward indices were 0 and the COMP speed was 0. A borrower with 18977306140567618322762 borrow units and no recorded borrower index claims 139 blocks after the upgrade, with both speeds still 0, and `CompRewards.comptroller` pays it 18977306140567618322762 (18,977.31 COMP). On mainnet this is transaction 0xc9244e5349f49f3b74a54a882e71f1ca11ba14ed74f73bf2cd091ed8be2b0001, block 13322937, 2021-09-29. Nothing was emitted to that market, so nothing should have been paid.",
  "definitions_under_repair": [
    "CompRewards.comptroller"
  ],
  "namespace": "CompRewards",
  "candidate": "candidate/Solution.lean",
  "locked_files": [
    "spec/CompRewards/Spec.lean",
    "spec/CompRewards/Challenge.lean"
  ],
  "requirements": [
    {
      "id": "REQ-CALLS-SUCCEED",
      "theorem": "CompRewards.req_calls_succeed",
      "statement": "CallsSucceed comptroller",
      "text": "REQ-CALLS-SUCCEED: in a consistent state, every call succeeds: the policy hooks for any account, claims and speed changes never revert."
    },
    {
      "id": "REQ-SUPPLY-HOOK",
      "theorem": "CompRewards.req_supply_hook",
      "statement": "SupplyHookEffects comptroller",
      "text": "REQ-SUPPLY-HOOK: a supply hook brings the supply index up to date and credits `who` for exactly the supply rewards since its start (`accrualStart`), rounded down; nothing else changes."
    },
    {
      "id": "REQ-BORROW-HOOK",
      "theorem": "CompRewards.req_borrow_hook",
      "statement": "BorrowHookEffects comptroller",
      "text": "REQ-BORROW-HOOK: a borrow hook brings the borrow index up to date and credits `who` for exactly the borrow rewards since its start, rounded down; nothing else changes."
    },
    {
      "id": "REQ-CLAIM",
      "theorem": "CompRewards.req_claim",
      "statement": "ClaimEffects comptroller",
      "text": "REQ-CLAIM: a claim credits `who` on both sides as the hooks do and then pays it everything it has accrued when the Comptroller holds enough COMP."
    },
    {
      "id": "REQ-SET-SPEEDS",
      "theorem": "CompRewards.req_set_speeds",
      "statement": "SetSpeedsEffects comptroller",
      "text": "REQ-SET-SPEEDS: a speed change accrues what was emitted at the old speed and then applies the new speeds."
    },
    {
      "id": "REQ-REWARDS-BOUNDED",
      "theorem": "CompRewards.req_rewards_bounded",
      "statement": "RewardsBounded comptroller",
      "text": "REQ-REWARDS-BOUNDED: from the upgrade of any well-formed pre-upgrade state, after any sequence of operations, the COMP paid out to accounts plus the COMP accrued to them never exceeds what they held or had accrued before the upgrade, plus what they were owed at the upgrade, plus the COMP emitted since."
    },
    {
      "id": "REQ-ACCOUNT-BOUNDED",
      "theorem": "CompRewards.req_account_bounded",
      "statement": "AccountBounded comptroller",
      "text": "REQ-ACCOUNT-BOUNDED: the same for every single account: from the upgrade of any well-formed pre-upgrade state, no account ever holds or has accrued more COMP than it held or had accrued before the upgrade, plus what it was owed at the upgrade, plus the COMP emitted since."
    },
    {
      "id": "REQ-NO-BACKDATED-REWARDS",
      "theorem": "CompRewards.req_no_backdated",
      "statement": "NoBackdatedRewards comptroller",
      "text": "REQ-NO-BACKDATED-REWARDS: an account is never credited for blocks before it held a position. In any state reached from the upgrade of a well-formed pre-upgrade state, if an account holds no position, then whatever happens next it gains at most the COMP emitted from then on."
    }
  ],
  "rules": {
    "edit_only": "candidate/Solution

